                stack.pop()
                on_path.discard(name)
                done.add(name)
                order.append(name)
                continue
            frame[2] += 1
            dep = deps[index]
            if dep in done:
                continue
            if dep in on_path:
                raise CycleError(
                    "cycle detected: %s" % " -> ".join(
                        [f[0] for f in stack] + [dep]
                    )
                )
            if dep not in asts:
                raise KeyError("unknown cell %r referenced by %r" % (dep, name))
            on_path.add(dep)
            stack.append([dep, _refs(asts[dep], []), 0])
    return order


def _eval(node, values):
    """Evaluate an AST whose references are all present in `values`."""
    tag = node[0]
    if tag == "num":
        return node[1]
    if tag == "ref":
        return values[node[1]]
    if tag == "neg":
        return -_eval(node[1], values)
    op = node[1]
    left = _eval(node[2], values)
    right = _eval(node[3], values)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        if right == 0:
            raise ZeroDivisionError("float division by zero")
        return left / right
    return float(left ** right)


def evaluate(cells):
    """Compute every cell's value.

    `cells` maps cell names to bare numbers or `=`-prefixed formulas; the
    result maps every one of those names to a float.
    """
    asts = {name: _parse_cell(text) for name, text in cells.items()}
    values = {}
    for name in _order(asts):
        values[name] = _eval(asts[name], values)
    return values

